// Run inside real Electron (needs the electron binary and xvfb-run). Setup used: unzip electron-v33 to /tmp/el/dist; build /tmp/elapp = main.js + preload.js extracted from .github/workflows/build-exe.yml plus a copy of the app in /tmp/elapp/www; serve a test page with an <img id=pic src=/pic.png> and <a id=lnk href=/page2.html> on http://localhost:8801; then: NODE_PATH=$(npm root -g) xvfb-run -a node el1.js
const { _electron: electron } = require('playwright');
const fs = require('fs');
let pass = 0, tot = 0;
const ok = (n, c, i) => { tot++; if (c) pass++; console.log((c ? 'PASS ' : 'FAIL ') + n + (!c && i !== undefined ? ' :: ' + JSON.stringify(i) : '')); };
(async () => {
  fs.rmSync('/tmp/eluser', { recursive: true, force: true });
  const app = await electron.launch({ executablePath: '/tmp/el/dist/electron', args: ['/tmp/elapp/main.js', '--no-sandbox', '--user-data-dir=/tmp/eluser'] });
  const pg = await app.firstWindow(); const errs = [];
  pg.on('pageerror', e => errs.push(String(e)));
  await pg.evaluate(() => { try { localStorage.setItem('msa_motion', 'off'); localStorage.setItem('msa_clean_v1', 'kept'); const d = new Date().toLocaleDateString('en-CA'); localStorage.setItem('msa_daily_m', d); localStorage.setItem('msa_daily_n', d); } catch (e) {} });
  await pg.reload(); await pg.waitForSelector('#lkPw', { timeout: 15000 }); await pg.fill('#lkPw', 'Akademia'); await pg.keyboard.press('Enter');
  await pg.waitForSelector('#app:not([hidden])', { timeout: 15000 }); await pg.waitForTimeout(600);
  await pg.evaluate(() => MSA.demo.load().then(() => { MSA.rerender && MSA.rerender(); })); await pg.waitForTimeout(1200);
  ok('desktop bridge exposes webview flag', await pg.evaluate(() => !!(window.msaDesktop && msaDesktop.webview && msaDesktop.onWebImage)));
  await pg.evaluate(() => MSA.explore.open(MSA.state.projects[0], { tab: 'sites' })); await pg.waitForSelector('#exBody .ex-srcs', { timeout: 8000 });
  ok('sites tab shows many famous sites', (await pg.locator('[data-ex-site]').count()) >= 10);
  const names = await pg.evaluate(() => [...document.querySelectorAll('[data-ex-site]')].map(x => x.textContent.trim()).join('|'));
  ok('includes Pinterest, Behance, Freepik', ['Pinterest', 'Behance', 'Freepik'].every(n => names.includes(n)), names);
  ok('webview element present', (await pg.locator('webview#exWv').count()) === 1);
  await pg.waitForTimeout(4000);
  await pg.evaluate(() => document.getElementById('exWv').setAttribute('src', 'http://localhost:8801/index.html'));
  await pg.waitForFunction(() => { const w = document.getElementById('exWv'); try { return w.getURL().includes('8801') && !w.isLoading(); } catch (e) { return false; } }, null, { timeout: 15000 });
  ok('embedded page loaded', (await pg.evaluate(() => document.getElementById('exWv').getURL())) === 'http://localhost:8801/index.html');
  const t = await pg.evaluate(() => document.getElementById('exWv').executeJavaScript('!!document.getElementById("pic")', true));
  ok('guest page content reachable', t === true, t);
  await pg.evaluate(() => document.getElementById('exWv').executeJavaScript('0', true));
  const iso = await pg.evaluate(() => document.getElementById('exWv').executeJavaScript('typeof require+"|"+typeof window.msaDesktop+"|"+typeof process'));
  ok('guest has no node/bridge access', iso === 'undefined|undefined|undefined', iso);
  await pg.evaluate(() => document.getElementById('exWv').executeJavaScript('document.getElementById("lnk").click()', true));
  await pg.waitForTimeout(2500); console.log('URL', await pg.evaluate(() => document.getElementById('exWv').getURL()), await pg.evaluate(() => document.getElementById('exWv').canGoBack()));
  await pg.waitForFunction(() => document.getElementById('exWv').getURL().includes('page2'), null, { timeout: 8000 });
  await pg.evaluate(() => { const w = document.getElementById('exWv'); window.__ev = []; ['did-navigate','did-navigate-in-page','did-start-navigation'].forEach(n => w.addEventListener(n, e => window.__ev.push(n + ':' + (e.url || '')))); });
  await pg.click('[data-ex=wv-back]'); await pg.waitForTimeout(2000); console.log('EV', JSON.stringify(await pg.evaluate(() => window.__ev))); console.log('URL2', await pg.evaluate(() => document.getElementById('exWv').getURL()), await pg.evaluate(()=>document.querySelector('[data-ex=wv-back]').outerHTML.slice(0,80)));
  await pg.waitForFunction(() => document.getElementById('exWv').getURL().includes('index.html'), null, { timeout: 8000 });
  ok('back button works', true);
  const before = await pg.evaluate(() => (MSA.state.projects[0].identity.images || []).length);
  const res = await app.evaluate(async ({ webContents }) => {
    const g = webContents.getAllWebContents().find(w => w.getType() === 'webview'); if (!g) return 'no guest';
    g.emit('context-menu', {}, { mediaType: 'image', srcURL: 'http://localhost:8801/pic.png', x: 10, y: 10, linkURL: '' });
    const m = global.__msaWebMenu; if (!m) return 'no menu';
    const labels = m.items.map(i => i.label || '-').join('|'); m.items[0].click(); return labels;
  });
  ok('context menu built with pin item', /Pin to my identity|تثبيت في هويتي/.test(String(res)), res);
  await pg.waitForTimeout(2000);
  const after = await pg.evaluate(() => (MSA.state.projects[0].identity.images || []).length);
  ok('image pinned to identity', after === before + 1, [before, after]);
  const sv = await pg.evaluate(() => { let n = 0; MSA.proj.walk(MSA.state.projects[0].steps, s => { (s.atts || []).forEach(a => { if (/^web-/.test(a.name)) n++; }); }); return n; });
  ok('image also saved as step attachment', sv === 1, sv);
  const w0 = app.windows().length;
  await pg.evaluate(() => document.getElementById('exWv').executeJavaScript('window.open("/page2.html")')); await pg.waitForTimeout(1200);
  ok('window.open does not spawn a window', app.windows().length === w0, app.windows().length);
  ok('no page errors', errs.length === 0, errs);
  await app.close();
  console.log(pass + '/' + tot + ' passed'); process.exit(pass === tot ? 0 : 1);
})().catch(e => { console.log('CRASH', e.message); process.exit(2); });
